<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Department,Mess,DepartmentLedger}; use Illuminate\Http\Request;
class AccountingController extends Controller { public function index(){ $departments=Department::orderBy('name')->get(); $messes=Mess::orderBy('name')->get(); $entries=DepartmentLedger::latest('entry_date')->limit(100)->get(); $costing=DepartmentLedger::selectRaw("department_id, sum(case when entry_type='DEBIT' then amount else -amount end) as net_cost")->groupBy('department_id')->get(); return view('admin.accounting.index',compact('departments','messes','entries','costing')); } public function storeDepartment(Request $r){ Department::create($r->validate(['name'=>'required','code'=>'required|unique:departments,code'])); return back()->with('success','Department created'); } public function storeMess(Request $r){ Mess::create($r->validate(['name'=>'required','code'=>'required|unique:messes,code','department_id'=>'nullable|exists:departments,id'])); return back()->with('success','Mess created'); } public function storeEntry(Request $r){ DepartmentLedger::create($r->validate(['department_id'=>'required|exists:departments,id','mess_id'=>'nullable|exists:messes,id','entry_date'=>'required|date','entry_type'=>'required|in:DEBIT,CREDIT','amount'=>'required|numeric|min:0.01'])+['remarks'=>$r->input('remarks')]); return back()->with('success','Ledger entry posted'); }}
